<?php require '../config/auth.php';login_required('student');$page_title='Job Opportunities';$q=trim($_GET['q']??'');$loc=trim($_GET['location']??'');$sql="SELECT j.*,c.company_name,c.logo FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.status='approved' AND j.application_deadline>=CURDATE()";$p=[];if($q){$sql.=' AND (j.job_title LIKE ? OR c.company_name LIKE ? OR j.required_skills LIKE ?)';$p=["%$q%","%$q%","%$q%"];}$sql.=' ORDER BY j.created_at DESC';$st=$pdo->prepare($sql);$st->execute($p);$jobs=$st->fetchAll();require '../config/header.php';?><div class="head"><div><h1>Job Opportunities</h1><p>Search approved placement opportunities.</p></div></div><form class="search"><input class="control" name="q" value="<?=e($q)?>" placeholder="Company, role or skill"><input class="control" name="location" value="<?=e($loc)?>" placeholder="Location"><button class="btn primary">Search</button></form><div class="grid g3"><?php foreach($jobs as $j):?><div class="card job"><div class="jobtop"><div class="logo"><?php if($j['logo']):?><img src="../<?=e($j['logo'])?>" style="width:100%;height:100%;object-fit:cover"><?php else:?>🏢<?php endif;?></div><div><h3><?=e($j['job_title'])?></h3><div class="muted small"><?=e($j['company_name'])?></div></div></div><div class="chips"><?php foreach(array_slice(explode(',',$j['required_skills']),0,4) as $sk):?><span class="chip"><?=e(trim($sk))?></span><?php endforeach;?></div><div class="meta"><span>📍 <?=e($j['location'])?></span><span>💰 <?=e($j['package_lpa'])?> LPA</span><span>👥 <?=$j['openings']?> openings</span><span>📅 <?=e($j['application_deadline'])?></span></div><div class="actions"><a class="btn outline sm" href="job-details.php?id=<?=$j['id']?>">View Details</a><a class="btn primary sm" href="job-details.php?id=<?=$j['id']?>">Apply</a></div></div><?php endforeach;?></div><?php if(!$jobs):?><div class="card empty">No approved jobs found.</div><?php endif;?><?php require '../config/footer.php';?>
